function ctc(r){var o=[];if(r.ml)o.push('<a href="mailto:'+esc(r.ml)+'" style="color:#1d5fa8;font-weight:700">✉️ '+esc(r.ml)+'</a>');if(r.tl)o.push('<a href="tel:'+esc(String(r.tl).replace(/[^\d+]/g,''))+'" style="color:#1d5fa8;font-weight:700;white-space:nowrap">📞 '+esc(r.tl)+'</a>');return o.join(' · ');}
function relBadge(r){var e=r.rl?-dj(r.rl):null;if(e==null)return stat(r)==='ko'?'<span style="font-size:12px;color:#737372;font-weight:700">jamais relancé</span> ':'';return e>7?'<span style="font-size:12px;color:#b21f2d;font-weight:800">⚠ relancé il y a '+e+' j, sans réponse</span> ':'<span style="font-size:12px;color:#1e7a34;font-weight:700">relancé le '+dd(r.rl).slice(0,5)+(e>0?' (il y a '+e+' j)':'')+'</span> ';}
function relMail(r){if(r.nx||!(stat(r)==='ko'||stat(r)==='wa'))return'';var sg='';try{sg=(JSON.parse(localStorage.getItem('ck_sigach')||'null')||{})[SS.mag]||'';}catch(e){}
var lab=(MAGS.filter(function(x){return x[0]===SS.mag;})[0]||[])[1]||SS.mag,j=dj(r.v),et=j<0?'est échu depuis '+(-j)+' jours (validité au '+dd(r.v)+')':'arrive à échéance dans '+j+' jours (validité au '+dd(r.v)+')';var sj='Weldom '+lab+' : '+r.org+', contrôle à planifier',bd='Bonjour,\n\nLe contrôle « '+r.org+' » de notre magasin Weldom '+lab+' '+et+', et aucun rendez-vous n\'est encore fixé.\n\nPourriez-vous nous proposer une date d\'intervention dans les meilleurs délais ?\n\nMerci d\'avance.\n\nCordialement,\n'+(sg||('Weldom '+lab));return relBadge(r)+'<a data-rl="'+esc(r.id)+'" href="mailto:'+esc(r.ml||'')+'?subject='+encodeURIComponent(sj)+'&body='+encodeURIComponent(bd)+'" style="display:inline-block;margin-top:5px;background:#1d5fa8;color:#fff;border-radius:999px;padding:4px 12px;font-weight:800;font-size:12.5px;text-decoration:none" title="'+(r.rl?'Relancer à nouveau. ':'')+(r.ml?'Mail déjà rédigé pour '+esc(r.int||'l\'entreprise'):'Mail déjà rédigé : renseigne le destinataire (ou saisis le mail dans la fiche)')+'">✉️ '+(r.rl?'Relancer à nouveau':'Relancer')+'</a>';}
