function item(r,kind){var c=COLS[stat(r)];return'<div class="sci" style="border-left:5px solid '+c[0]+'"><b>'+esc(r.ic||'🧯')+' '+esc(r.org)+'</b>'+((r.int&&r.org.toLowerCase().indexOf(r.int.toLowerCase())<0)?' <span class="scm">· '+esc(r.int)+'</span>':'')+'<div class="scm">'+(kind==='fait'?'Fait le <b>'+dd(r.dr)+'</b>':'Échéance <b>'+dd(due(r))+'</b>'+(r.nx?' (RDV fixé)':' · <b style="color:#b21f2d">à planifier / relancer</b>'))+(r.dv?' · <span class="scd">Devis '+esc(r.dv.toLowerCase())+'</span>':'')+'</div>'+(kind!=='fait'&&(ctc(r)||relMail(r))?'<div class="scm">'+ctc(r)+(ctc(r)&&relMail(r)?'<br>':'')+relMail(r)+'</div>':'')+(r.rm?'<div class="scr">'+esc(r.rm)+'</div>':'')+(r.ob?'<div class="scr">↳ '+esc(r.ob)+'</div>':'')+'</div>';}
