function card1(r){var s=stat(r),c=COLS[s],j=r.v?dj(r.v):null,rel=(s==='ko'||s==='wa')&&!r.nx;var top='<div style="display:flex;gap:9px;align-items:center"><span style="font-size:28px">'+esc(r.ic||'🧯')+'</span><div style="font-weight:800;font-size:15px;line-height:1.15">'+(SS.edit?inp(r,'org','text','Organe'):esc(r.org))+'</div></div>';if(!SS.edit)return'<div class="scc" style="border-top:7px solid '+c[0]+'">'+top+'<div class="scm">'+((r.int&&r.org.toLowerCase().indexOf(r.int.toLowerCase())<0)?esc(r.int):'')+'</div><div style="background:'+c[1]+';color:'+c[0]+';border-radius:10px;padding:7px 10px;font-weight:800;font-size:13px">'+c[2]+(j==null?'':' · '+(j<0?'échu depuis '+(-j)+' j':'dans '+j+' j'))+'</div>'+(rel?'<div class="screl">📞 Relancer '+esc(r.int||'l\'entreprise')+' : aucun RDV fixé'+(ctc(r)?'<br>'+ctc(r):'')+'<br>'+relMail(r)+'</div>':'')
+'<div class="scg"><span>Dernière venue<b>'+dd(r.dr)+'</b></span><span>Prochaine date<b>'+dd(due(r))+(r.nx?' <small>RDV</small>':'')+'</b></span></div><div class="scg"><span>Valide jusqu\'au<b>'+dd(r.v)+'</b></span><span>Devis<b>'+esc(r.dv||'—')+'</b></span></div>'+(r.rm?'<div class="scr">'+esc(r.rm)+'</div>':'')+(r.ob?'<div class="scr">↳ '+esc(r.ob)+'</div>':'')+(r.lv?'<div class="scm">Levée le '+dd(r.lv)+'</div>':'')+'</div>';return'<div class="scc" style="border-top:7px solid '+c[0]+'">'+top+'<label class="scl">Intervenant (entreprise)'+inp(r,'int','text','Nom de l\'entreprise')+'</label><label class="scl">Mail (adresse générique)'+inp(r,'ml','email','contact@…')+'</label><label class="scl">Téléphone'+inp(r,'tl','tel','03 89 00 00 00')+'</label><div class="scfq"><span>Fréquence de visite</span>'+[['a','Annuel'],['s','Semestriel'],['t','Triennal']].map(function(q){return'<button type="button" data-fqid="'+r.id+'" data-fq="'+q[0]+'" class="'+(r.fq===q[0]?'on':'')+'">'+q[1]+'</button>';}).join('')+'<small>'+(r.fq?'« Valide jusqu\'au » se calcule tout seul à la saisie de la dernière venue':'choisis la fréquence : « Valide jusqu\'au » se calculera tout seul')+'</small></div><div class="scg2"><label class="scl">Dernière venue'+inp(r,'dr','date','')+'</label><label class="scl">Prochain RDV'+inp(r,'nx','date','')+'</label><label class="scl">Valide jusqu\'au'+inp(r,'v','date','')+'</label><label class="scl">Levée le'+inp(r,'lv','date','')+'</label><label class="scl">Dernière relance'+inp(r,'rl','date','')+'</label></div><label class="scl">Devis<select data-id="'+r.id+'" data-f="dv" class="scin">'+DVS.map(function(x){return'<option value="'+x+'"'+(x===(r.dv||'')?' selected':'')+'>'+(x||'— aucun —')+'</option>';}).join('')+'</select></label><label class="scl">Remarques sur rapport<textarea data-id="'+r.id+'" data-f="rm" class="scin" rows="2">'+esc(r.rm||'')+'</textarea></label><label class="scl">Observations du responsable<textarea data-id="'+r.id+'" data-f="ob" class="scin" rows="2">'+esc(r.ob||'')+'</textarea></label><button type="button" data-del="'+r.id+'" class="scdel">✕ Supprimer cet organe</button></div>';}
