function anoHtml(){var L=anoL(),n=L.filter(function(x){return x.st!=='r';}).length,F=SS.fo,orgs=rows().map(function(r){return r.org;});var h='<section class="sca"><div class="scah"><h3 class="sch" style="margin:0">⚠️ Anomalies signalées <span class="scm">('+n+' ouverte'+(n>1?'s':'')+')</span></h3><button type="button" class="cb" id="anoadd" style="background:#b21f2d;color:#fff">⚠️ Signaler un problème</button></div>'+(SS.msg?'<div class="scm" style="margin:6px 0;font-weight:700">'+esc(SS.msg)+'</div>':'');var dmA=SS.dm[SS.mag]||'';if(SS.last&&SS.last.m===SS.mag){var X=SS.last,lab=(MAGS.filter(function(x){return x[0]===SS.mag;})[0]||[])[1]||SS.mag,sj='Weldom '+lab+' : anomalie de sécurité signalée',bd='Bonjour,\n\nUne anomalie de sécurité vient d\'être signalée dans le magasin Weldom '+lab+'.\n\nOrgane : '+(X.org||'autre / général')+'\nConstat : '+X.tx+'\nDate : '+dd(X.dt)+(X.ph?'\n(Photo à consulter dans Cockpit 360, page Sécurité incendie.)':'')+'\n\nMerci de la prendre en charge et de valider sa résolution dans l\'outil.\n\nCordialement';h+='<div class="scmail">'+(dmA?'<a href="mailto:'+esc(dmA)+'?subject='+encodeURIComponent(sj)+'&body='+encodeURIComponent(bd)+'" class="cb dk" style="text-decoration:none;display:inline-block">✉️ Prévenir le directeur par mail</a>':'<span class="scm">Adresse du directeur non renseignée : 🔓 Modifier, puis la saisir dans « Mail du directeur ».</span>')+' <button type="button" class="scdel" id="anolx">Fermer</button></div>';}
if(SS.edit)h+='<label class="scl" style="max-width:420px;margin:6px 0">Mail du directeur (adresse du magasin, sans nom de personne)<input id="dmail" type="email" class="scin scx" value="'+esc(dmA)+'" placeholder="direction.magasin@…"></label>';if(F)h+='<div class="scaf"><label class="scl">Organe concerné<select id="ano_o" class="scin scx"><option value="">Autre / général</option>'+orgs.map(function(o){return'<option'+(F.o===o?' selected':'')+'>'+esc(o)+'</option>';}).join('')+'</select></label><label class="scl">Que se passe-t-il ?<textarea id="ano_t" class="scin scx" rows="3" maxlength="400" placeholder="ex. goupille manquante, issue de secours encombrée…">'+esc(F.t)+'</textarea></label><div class="scap">'+(F.ps.length<3?'<label class="cb" style="cursor:pointer">📷 Ajouter une photo ('+F.ps.length+'/3)<input type="file" id="ano_f" accept="image/*" capture="environment" hidden></label>':'')+F.ps.map(function(d,i){return'<span class="scth"><img src="'+d+'" alt=""><button type="button" class="scdel" data-px="'+i+'">✕</button></span>';}).join('')+(F.ps.length?'':'<span class="scm">facultatives · jusqu\'à 3 · réduites automatiquement</span>')+'</div><div style="display:flex;gap:8px"><button type="button" class="cb dk" id="ano_ok">Envoyer le signalement</button>'+(F.ps.length?'<button type="button" class="cb" id="ano_nop" title="Envoie le signalement sans les photos">Envoyer sans photo</button>':'')+'<button type="button" class="cb" id="ano_no">Annuler</button></div></div>';h+=L.length?'<div class="scgrid">'+L.map(function(a){var c=AST[a.st]||AST.o;return'<div class="scc" style="border-left:7px solid '+c[2]+'"><div style="display:flex;justify-content:space-between;gap:8px;align-items:center"><b>'+(a.org?esc(a.org):'Autre / général')+'</b><span class="scst" style="background:'+c[3]+';color:'+c[2]+'">'+c[0]+' '+c[1]+'</span></div><div class="scr" style="font-size:13.5px">'+esc(a.tx)+'</div><div class="scm">Signalé le '+dd(a.dt)+(a.vd?' · résolu le '+dd(a.vd):'')+'</div>'+(a.ph?'<div data-phw="'+esc(a.id)+'">'+(SS.ph[a.id]?SS.ph[a.id].map(function(d){return'<img class="scph" src="'+d+'" alt="">';}).join(''):'<button type="button" class="cb" data-ph="'+esc(a.id)+'" data-n="'+(+a.ph)+'">📷 Voir '+(a.ph>1?'les '+a.ph+' photos':'la photo')+'</button>')+'</div>':'')
+(isDir()?'<div class="scd">'+(a.st==='o'?'<button type="button" class="cb" data-as="c" data-id="'+esc(a.id)+'">🟠 Prendre en charge</button>':'')+(a.st!=='r'?'<button type="button" class="cb" style="background:#1e7a34;color:#fff" data-as="r" data-id="'+esc(a.id)+'">✅ Valider la résolution</button>':'<button type="button" class="cb" data-as="o" data-id="'+esc(a.id)+'">↩ Rouvrir</button>')+'<button type="button" class="scdel" data-ad="'+esc(a.id)+'">'+(SS.del===a.id?'⚠ Confirmer':'Supprimer')+'</button></div>':'')+'</div>';}).join('')+'</div>':'<div class="scm" style="margin-top:6px">Aucune anomalie signalée.</div>';return h+'</section>';}
function anoPatch(fn,msg){SS.msg='Enregistrement…';draw();return window.__chifEd.patch(function(o){o.ano=o.ano||{};o.ano[SS.mag]=o.ano[SS.mag]||[];fn(o.ano[SS.mag]);}).then(function(ok){if(ok){fn(SS.ano[SS.mag]=SS.ano[SS.mag]||[]);SS.msg=msg;}else SS.msg='Enregistrement impossible (connexion ou accès).';draw();setTimeout(function(){if(SS.msg===msg){SS.msg='';draw();}},4000);}).catch(function(){SS.msg='Enregistrement impossible (connexion ou accès).';draw();});}
function reduirePh(file){return new Promise(function(ok,ko){var r=new FileReader();r.onerror=ko;r.onload=function(){var im=new Image();im.onerror=ko;im.onload=function(){var W=[640,520,420,340],Q=[.55,.5,.45,.4],i=0,out;(function essai(){var k=Math.min(1,W[i]/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);out=c.toDataURL('image/jpeg',Q[i]);if(out.length>26000&&i<3){i++;essai();}else ok(out.length>26000?'':out);})();};im.src=r.result;};r.readAsDataURL(file);});}
function wireAno(){var q=function(i){return ov.querySelector(i);},rd=function(){if(!SS.fo)return;SS.fo.o=(q('#ano_o')||{}).value||'';SS.fo.t=((q('#ano_t')||{}).value||'').trim();};var ad=q('#anoadd');if(ad)ad.onclick=function(){SS.fo={o:'',t:'',ps:[]};SS.msg='';draw();};if(SS.fo){q('#ano_no').onclick=function(){SS.fo=null;draw();};var fi=q('#ano_f');if(fi)fi.onchange=async function(){rd();var f=this.files&&this.files[0];if(!f)return;try{var d=await reduirePh(f);if(!d)SS.msg='Photo trop lourde : reprends-la de plus loin.';else if(SS.fo.ps.length<3)SS.fo.ps.push(d);}catch(e){SS.msg='Photo illisible.';}draw();};ov.querySelectorAll('button[data-px]').forEach(function(b){b.onclick=function(){rd();SS.fo.ps.splice(+b.dataset.px,1);draw();};});var envoi=async function(sansPhoto){rd();if(!SS.fo.t){SS.msg='Décris le problème en quelques mots.';draw();return;}
var id='a'+Date.now().toString(36)+Math.random().toString(36).slice(2,4),F=SS.fo,ph=0;if(sansPhoto)F.ps=[];if(F.ps.length){SS.msg='Envoi des photos…';draw();for(var pi=0;pi<F.ps.length;pi++){var ok=false;try{ok=await window.__chifEd.putX(phKey(id,pi),'secp'+SS.mag,{p:F.ps[pi]});}catch(e){}if(!ok){SS.msg='Une photo n’a pas été acceptée par Google'+(window.__putErr?' ('+window.__putErr+')':'')+' : signalement non envoyé. Réessaie ou envoie sans photo.';draw();return;}}ph=F.ps.length;SS.ph[id]=F.ps.slice();}
var it={id:id,org:F.o,tx:F.t,dt:TI,st:'o',ph:ph};SS.fo=null;SS.last={m:SS.mag,org:F.o,tx:F.t,dt:TI,ph:ph};anoPatch(function(a){if(!a.some(function(x){return x.id===id;}))a.push(it);},'Signalement envoyé.');};q('#ano_ok').onclick=function(){envoi(false);};var nop=q('#ano_nop');if(nop)nop.onclick=function(){envoi(true);};}
var lx=q('#anolx');if(lx)lx.onclick=function(){SS.last=null;draw();};var dmi=q('#dmail');if(dmi)dmi.onchange=async function(){var v=dmi.value.trim(),mg=SS.mag,ok=false;if(v&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)){SS.msg='Adresse mail non valide.';draw();return;}try{ok=await window.__chifEd.patch(function(o){o.dm=o.dm||{};if(v)o.dm[mg]=v;else delete o.dm[mg];});}catch(e){}if(ok){if(v)SS.dm[mg]=v;else delete SS.dm[mg];}if(window.__vpill)window.__vpill(dmi,!!ok);};ov.querySelectorAll('button[data-sg]').forEach(function(b){b.onclick=function(){var r=rows().filter(function(x){return x.id===b.dataset.sg;})[0];SS.fo={o:r?r.org:'',t:'',ps:[]};SS.msg='';draw();var a=ov.querySelector('.sca');if(a)a.scrollIntoView({block:'start'});};});ov.querySelectorAll('button[data-ph]').forEach(function(b){b.onclick=async function(){var id=b.dataset.ph,n=+b.dataset.n||1;b.textContent='Chargement…';var out=[];for(var i=0;i<n;i++){var d=null;try{d=await window.__chifEd.getX(phKey(id,i),'secp'+SS.mag);}catch(e){}if(d&&d.p)out.push(d.p);}if(out.length){SS.ph[id]=out;draw();}else b.textContent='Photo introuvable';};});ov.querySelectorAll('button[data-as]').forEach(function(b){b.onclick=function(){var id=b.dataset.id,st=b.dataset.as;anoPatch(function(a){var x=a.filter(function(y){return y.id===id;})[0];if(x){x.st=st;if(st==='r')x.vd=TI;else delete x.vd;}},st==='r'?'Anomalie validée comme résolue.':'Statut mis à jour.');};});ov.querySelectorAll('button[data-ad]').forEach(function(b){b.onclick=function(){var id=b.dataset.ad;if(SS.del!==id){SS.del=id;draw();return;}SS.del='';anoPatch(function(a){var k=a.findIndex(function(y){return y.id===id;});if(k>=0)a.splice(k,1);},'Anomalie supprimée.');};});}
